/**
 * Status report of one orchestrator (`orkumo report`): the full current state of the work it
 * coordinates, sent as a snapshot every time. The server keeps the latest report per orchestrator
 * and derives the change log by comparing snapshots. An inbox entry that is missing from the next
 * report counts as closed by the orchestrator.
 *
 * Source of truth for the published JSON Schema (`server/orchestrator/report.schema.json`,
 * generated by `scripts/orchestrator-report-schema.mjs`).
 */
import { z } from 'zod';

export const REPORT_SCHEMA_VERSION = 1;
export const TASK_STATES = ['planned', 'running', 'waiting', 'done', 'cancelled'];
export const INBOX_KINDS = ['decision', 'todo', 'approval'];

const id = z.string().regex(/^[\w.:-]{1,200}$/);
const text = (max) => z.string().trim().min(1).max(max);
const url = z.string().url().max(500);
const time = z.iso.datetime({ offset: true });

const refs = z
  .object({
    prs: z.array(url).max(50).optional().describe('PR URLs'),
    issues: z.array(url).max(50).optional().describe('Issue URLs; also the key that merges board items'),
    agents: z.array(id).max(50).optional().describe('Orkumo agent ids (as in `orkumo agents`)'),
  })
  .strict();

const task = z
  .object({
    id,
    title: text(200),
    state: z.enum(TASK_STATES),
    note: text(1000).optional().describe('One line: what happens now or what blocks'),
    refs: refs.optional(),
    updatedAt: time.optional(),
  })
  .strict();

const project = z
  .object({
    id,
    name: text(120),
    repo: z.string().regex(/^[\w.-]+\/[\w.-]+$/).optional().describe('owner/name'),
    tasks: z.array(task).max(200),
  })
  .strict();

const inboxBase = {
  id: id.describe('Stable across reports; answers are keyed by it'),
  title: text(200),
  detail: text(4000).optional(),
  projectId: id.optional(),
  taskId: id.optional(),
  priority: z.enum(['high', 'normal', 'low']).optional(),
  createdAt: time,
  refs: refs.optional(),
};

const option = z.object({ id, label: text(200), detail: text(1000).optional() }).strict();

const inboxEntry = z.discriminatedUnion('kind', [
  z
    .object({
      ...inboxBase,
      kind: z.literal('decision'),
      options: z.array(option).min(2).max(8),
      recommendation: id.describe('id of one of the options'),
    })
    .strict()
    .refine((e) => e.options.some((o) => o.id === e.recommendation), {
      message: 'recommendation must be the id of one of the options',
      path: ['recommendation'],
    }),
  z.object({ ...inboxBase, kind: z.literal('todo') }).strict(),
  z.object({ ...inboxBase, kind: z.literal('approval'), pr: url }).strict(),
]);

export const reportSchema = z
  .object({
    schemaVersion: z.literal(REPORT_SCHEMA_VERSION),
    orchestrator: z.object({ id, name: text(120).optional() }).strict(),
    reportedAt: time,
    summary: text(2000).optional(),
    projects: z.array(project).max(100),
    inbox: z.array(inboxEntry).max(100),
    extensions: z
      .record(z.string().regex(/^x-[\w.-]+$/), z.unknown())
      .optional()
      .describe('Free data for other readers; keys start with "x-"'),
  })
  .strict();

/** @returns {{ ok: true, report: object } | { ok: false, errors: string[] }} */
export function parseReport(input) {
  const result = reportSchema.safeParse(input);
  if (result.success) return { ok: true, report: result.data };
  return {
    ok: false,
    errors: result.error.issues.map((i) => `${i.path.join('.') || '(root)'}: ${i.message}`),
  };
}
